<?php use Hls\Http\View as V; ?>
<?php if($error): ?><div class="alert alert-error"><?= V::escape($error) ?></div><?php endif ?>
<?php if($access->can('finance.payment.create')): ?><section class="panel"><form method="post" class="form-grid" data-payment-form><?= $this->csrf() ?><label>Rekening<select name="account_id" required><?php foreach($accounts as $a): ?><option value="<?= (int)$a['id'] ?>"><?= V::escape($a['code'].' - '.$a['name']) ?></option><?php endforeach ?></select></label><label>Tanggal pembayaran<input type="date" name="payment_date" value="<?= date('Y-m-d') ?>" required></label><label>Referensi pembayaran<input name="payment_ref" maxlength="50" placeholder="Opsional"></label><fieldset><legend>Alokasi invoice</legend><?php foreach($invoices as $i): ?><label class="payment-allocation-row"><input type="checkbox" class="payment-invoice-check" name="invoice_id[]" value="<?= (int)$i['id'] ?>"><span><?= V::escape($i['official_number']) ?> Â· <?= V::escape($i['customer_name']) ?> Â· Sisa <?= \Hls\Http\View::money($i['remaining']) ?></span><input class="payment-allocation" name="allocation[]" type="number" min="0.01" max="<?= V::escape($i['remaining']) ?>" step="0.01" placeholder="Nominal alokasi" disabled></label><?php endforeach ?></fieldset><p>Total alokasi: <strong data-allocation-total>Rp 0</strong></p><button class="button button-primary" type="submit">Catat Pembayaran</button></form></section><?php endif ?>
<section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Referensi Pembayaran</th><th>Customer</th><th>Invoice</th><th>Rekening</th><th>Nominal</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= V::escape($r['payment_date']) ?></td><td><?= V::escape($r['payment_ref']) ?></td><td><?= V::escape($r['customer_name']) ?></td><td><?= V::escape($r['official_number']) ?></td><td><?= V::escape($r['account_code']) ?></td><td><?= \Hls\Http\View::money($r['allocated']) ?></td><td><?= V::escape($r['status']) ?></td><td><?php if($r['status']==='POSTED'&&$access->can('finance.payment.reverse')): ?><form method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="reverse"><input type="hidden" name="payment_id" value="<?= (int)$r['id'] ?>"><input name="reason" required placeholder="Alasan reversal"><button class="button" type="submit">Reversal</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table><?php if(!$rows): ?><p class="empty-state">Belum ada transaksi pembayaran.</p><?php endif ?></div></section>